  5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  6	import com.pousadamarealta.api.*;
  7	import com.pousadamarealta.database.Database;
  8	import com.pousadamarealta.database.DatabaseMigration;
  9	import com.pousadamarealta.document.DocumentGeneratorFactory;
 10	import com.pousadamarealta.repository.MessageRepository;
 11	import com.pousadamarealta.repository.ReservationRepository;
 12	import com.pousadamarealta.repository.RoomRepository;
 13	import com.pousadamarealta.service.EmailService;
 14	import com.pousadamarealta.service.ReportService;
 15	import com.pousadamarealta.service.ReservationService;
 16	import com.pousadamarealta.service.RoomService;
 17	import io.javalin.Javalin;
 18	import io.javalin.json.JavalinJackson;
 19	
 20	import java.sql.SQLException;
 21	
 22	public class App {
 23	    public static void main(String[] args) throws SQLException {
 24	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 25	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
 26	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
 27	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 28	
 29	        Database database = new Database(dbUrl, dbUser, dbPassword);
 30	        DatabaseMigration migration = new DatabaseMigration(database);
 31	        migration.migrate();
 32	
 33	        RoomRepository roomRepository = new RoomRepository(database);
 34	        ReservationRepository reservationRepository = new ReservationRepository(database);
 35	        MessageRepository messageRepository = new MessageRepository(database);
 36	
 37	        DocumentGeneratorFactory documentGeneratorFactory = new DocumentGeneratorFactory();
 38	
 39	        RoomService roomService = new RoomService(roomRepository);
 40	        EmailService emailService = new EmailService(messageRepository, documentGeneratorFactory);
 41	        ReservationService reservationService = new ReservationService(
 42	            reservationRepository,
 43	            roomService,
 44	            emailService,
 45	            documentGeneratorFactory
 46	        );
 47	        ReportService reportService = new ReportService(reservationRepository, roomService);
 48	
 49	        RoomController roomController = new RoomController(roomService);
 50	        ReservationController reservationController = new ReservationController(reservationService, roomService);
 51	        MessageController messageController = new MessageController(messageRepository);
 52	        ReportController reportController = new ReportController(reportService);
 53	
 54	        ObjectMapper objectMapper = new ObjectMapper();
 55	        objectMapper.registerModule(new JavaTimeModule());
 56	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 57	
 58	        Javalin app = Javalin.create(config -> {
 59	            config.jsonMapper(new JavalinJackson(objectMapper, false));
 60	        });
 61	
 62	        app.get("/rooms", roomController::getRooms);
 63	        app.post("/reservations", reservationController::createReservation);
 64	        app.get("/reservations/{id}", reservationController::getReservation);
 65	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 66	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 67	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 68	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 69	        app.get("/reservations/{id}/document", reservationController::getDocument);
 70	        app.get("/messages", messageController::getMessages);
 71	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 72	        app.get("/reports/revenue", reportController::getRevenueReport);
 73	
 74	        app.start(port);
 75	    }
 76	}
