100	import io.javalin.http.Context;
101	
102	import java.sql.SQLException;
103	import java.util.HashMap;
104	import java.util.List;
105	import java.util.Map;
106	import java.util.stream.Collectors;
107	
108	public class MessageController {
109	    private final MessageRepository messageRepository;
110	
111	    public MessageController(MessageRepository messageRepository) {
112	        this.messageRepository = messageRepository;
113	    }
114	
115	    public void getMessages(Context ctx) throws SQLException {
116	        List<Message> messages = messageRepository.findAll();
117	        List<Map<String, Object>> response = messages.stream()
118	            .map(this::mapMessageToResponse)
119	            .collect(Collectors.toList());
120	        ctx.json(response);
121	    }
122	
123	    private Map<String, Object> mapMessageToResponse(Message message) {
124	        Map<String, Object> map = new HashMap<>();
125	        map.put("id", message.getId());
126	        map.put("channel", message.getChannel().name());
127	        map.put("to", message.getTo());
128	        map.put("subject", message.getSubject());
129	        map.put("body", message.getBody());
130	        return map;
131	    }
132	}
