140	import java.time.YearMonth;
141	import java.time.format.DateTimeParseException;
142	
143	public class ReportController {
144	    private final ReportService reportService;
145	
146	    public ReportController(ReportService reportService) {
147	        this.reportService = reportService;
148	    }
149	
150	    public void getOccupancyReport(Context ctx) throws SQLException {
151	        try {
152	            String dateParam = ctx.queryParam("date");
153	            if (dateParam == null) {
154	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing date parameter"));
155	                return;
156	            }
157	
158	            LocalDate date = LocalDate.parse(dateParam);
159	            String csv = reportService.generateOccupancyReport(date);
160	
161	            ctx.contentType("text/csv; charset=utf-8");
162	            ctx.result(csv);
163	
164	        } catch (DateTimeParseException e) {
165	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
166	        }
167	    }
168	
169	    public void getRevenueReport(Context ctx) throws SQLException {
170	        try {
171	            String monthParam = ctx.queryParam("month");
172	            if (monthParam == null) {
173	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing month parameter"));
174	                return;
175	            }
176	
177	            YearMonth yearMonth = YearMonth.parse(monthParam);
178	            String csv = reportService.generateRevenueReport(yearMonth.getYear(), yearMonth.getMonthValue());
179	
180	            ctx.contentType("text/csv; charset=utf-8");
181	            ctx.result(csv);
182	
183	        } catch (DateTimeParseException e) {
184	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
185	        }
186	    }
187	}
