203	public class ReservationController {
204	    private final ReservationService reservationService;
205	    private final RoomService roomService;
206	
207	    public ReservationController(ReservationService reservationService, RoomService roomService) {
208	        this.reservationService = reservationService;
209	        this.roomService = roomService;
210	    }
211	
212	    public void createReservation(Context ctx) throws SQLException {
213	        try {
214	            JsonNode json = ctx.bodyAsClass(JsonNode.class);
215	
216	            Reservation reservation = new Reservation();
217	
218	            if (!json.has("roomNumber") || !json.has("guestName") || !json.has("guestEmail") ||
219	                !json.has("checkIn") || !json.has("checkOut") || !json.has("guests") || !json.has("ratePlan")) {
220	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
221	                return;
222	            }
223	
224	            reservation.setRoomNumber(json.get("roomNumber").asText());
225	            reservation.setGuestName(json.get("guestName").asText());
226	            reservation.setGuestEmail(json.get("guestEmail").asText());
227	            reservation.setGuests(json.get("guests").asInt());
228	
229	            try {
230	                reservation.setCheckIn(LocalDate.parse(json.get("checkIn").asText()));
231	                reservation.setCheckOut(LocalDate.parse(json.get("checkOut").asText()));
232	            } catch (DateTimeParseException e) {
233	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
234	                return;
235	            }
236	
237	            if (reservation.getCheckOut().isBefore(reservation.getCheckIn()) ||
238	                reservation.getCheckOut().equals(reservation.getCheckIn())) {
239	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Check-out must be after check-in"));
240	                return;
241	            }
242	
243	            if (reservation.getGuests() < 1) {
244	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "At least one guest required"));
245	                return;
246	            }
247	
248	            try {
249	                reservation.setRatePlan(RatePlan.valueOf(json.get("ratePlan").asText()));
250	            } catch (IllegalArgumentException e) {
251	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid rate plan"));
252	                return;
253	            }
254	
255	            int identificationFields = 0;
256	            if (json.has("guestCpf") && !json.get("guestCpf").isNull()) {
257	                reservation.setGuestCpf(json.get("guestCpf").asText());
258	                identificationFields++;
259	            }
260	            if (json.has("companyCnpj") && !json.get("companyCnpj").isNull()) {
261	                if (!json.has("companyName") || json.get("companyName").isNull()) {
262	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Company CNPJ requires company name"));
263	                    return;
264	                }
265	                reservation.setCompanyCnpj(json.get("companyCnpj").asText());
266	                reservation.setCompanyName(json.get("companyName").asText());
267	                identificationFields++;
268	            }
269	            if (json.has("guestPassport") && !json.get("guestPassport").isNull()) {
270	                if (!json.has("guestCountry") || json.get("guestCountry").isNull()) {
271	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Guest passport requires guest country"));
272	                    return;
273	                }
274	                reservation.setGuestPassport(json.get("guestPassport").asText());
275	                reservation.setGuestCountry(json.get("guestCountry").asText());
276	                identificationFields++;
277	            }
278	
279	            if (identificationFields != 1) {
280	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Exactly one guest identification method required"));
281	                return;
282	            }
283	
284	            Optional<Room> room = roomService.getRoomByNumber(reservation.getRoomNumber());
285	            if (room.isEmpty()) {
286	                ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
287	                return;
288	            }
289	
290	            if (reservation.getGuests() > room.get().getCapacity()) {
291	                ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
292	                return;
293	            }
294	
295	            Reservation created = reservationService.createReservation(reservation);
296	            ctx.status(201).json(mapReservationToResponse(created, room.get()));
297	
298	        } catch (IllegalArgumentException e) {
299	            if (e.getMessage().equals("Room unavailable")) {
300	                ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
301	            } else {
302	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
303	            }
304	        }
305	    }
306	
307	    public void getReservation(Context ctx) throws SQLException {
308	        try {
309	            Long id = Long.parseLong(ctx.pathParam("id"));
310	            Optional<Reservation> reservation = reservationService.getReservation(id);
311	
312	            if (reservation.isEmpty()) {
313	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
314	                return;
315	            }
316	
317	            Room room = roomService.getRoomByNumber(reservation.get().getRoomNumber())
318	                .orElseThrow(() -> new IllegalStateException("Room not found"));
319	
320	            ctx.json(mapReservationToResponse(reservation.get(), room));
321	
322	        } catch (NumberFormatException e) {
323	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
324	        }
325	    }
326	
327	    public void confirmReservation(Context ctx) throws SQLException {
328	        try {
329	            Long id = Long.parseLong(ctx.pathParam("id"));
330	            Reservation reservation = reservationService.confirmReservation(id);
331	
332	            Room room = roomService.getRoomByNumber(reservation.getRoomNumber())
333	                .orElseThrow(() -> new IllegalStateException("Room not found"));
334	
335	            ctx.json(mapReservationToResponse(reservation, room));
336	
337	        } catch (NumberFormatException e) {
338	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
339	        } catch (IllegalArgumentException e) {
340	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
341	        } catch (IllegalStateException e) {
342	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Cannot confirm reservation in current status"));
343	        }
344	    }
345	
346	    public void checkIn(Context ctx) throws SQLException {
347	        try {
348	            Long id = Long.parseLong(ctx.pathParam("id"));
349	            Reservation reservation = reservationService.checkIn(id);
350	
351	            Room room = roomService.getRoomByNumber(reservation.getRoomNumber())
352	                .orElseThrow(() -> new IllegalStateException("Room not found"));
353	
354	            ctx.json(mapReservationToResponse(reservation, room));
355	
356	        } catch (NumberFormatException e) {
357	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
358	        } catch (IllegalArgumentException e) {
359	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
360	        } catch (IllegalStateException e) {
361	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Cannot check-in reservation in current status"));
362	        }
363	    }
364	
365	    public void checkOut(Context ctx) throws SQLException {
366	        try {
367	            Long id = Long.parseLong(ctx.pathParam("id"));
368	            Document document = reservationService.checkOut(id);
369	
370	            ctx.json(mapDocumentToResponse(document));
371	
372	        } catch (NumberFormatException e) {
373	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
374	        } catch (IllegalArgumentException e) {
375	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
376	        } catch (IllegalStateException e) {
377	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Cannot check-out reservation in current status"));
378	        }
379	    }
380	
381	    public void cancelReservation(Context ctx) throws SQLException {
382	        try {
383	            Long id = Long.parseLong(ctx.pathParam("id"));
384	            Reservation reservation = reservationService.cancelReservation(id);
385	
386	            Room room = roomService.getRoomByNumber(reservation.getRoomNumber())
387	                .orElseThrow(() -> new IllegalStateException("Room not found"));
388	
389	            ctx.json(mapReservationToResponse(reservation, room));
390	
391	        } catch (NumberFormatException e) {
392	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
393	        } catch (IllegalArgumentException e) {
394	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
395	        } catch (IllegalStateException e) {
396	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Cannot cancel reservation in current status"));
397	        }
398	    }
399	
400	    public void getDocument(Context ctx) throws SQLException {
401	        try {
402	            Long id = Long.parseLong(ctx.pathParam("id"));
403	            Document document = reservationService.getDocument(id);
404	
405	            ctx.json(mapDocumentToResponse(document));
406	
407	        } catch (NumberFormatException e) {
408	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
409	        } catch (IllegalArgumentException e) {
410	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
411	        } catch (IllegalStateException e) {
412	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Document not available"));
413	        }
414	    }
415	
416	    private Map<String, Object> mapReservationToResponse(Reservation reservation, Room room) {
417	        Map<String, Object> map = new HashMap<>();
418	        map.put("id", reservation.getId());
419	        map.put("roomNumber", reservation.getRoomNumber());
420	        map.put("guestName", reservation.getGuestName());
421	        map.put("guestEmail", reservation.getGuestEmail());
422	        map.put("guestCpf", reservation.getGuestCpf());
423	        map.put("companyCnpj", reservation.getCompanyCnpj());
424	        map.put("companyName", reservation.getCompanyName());
425	        map.put("guestPassport", reservation.getGuestPassport());
426	        map.put("guestCountry", reservation.getGuestCountry());
427	        map.put("checkIn", reservation.getCheckIn());
428	        map.put("checkOut", reservation.getCheckOut());
429	        map.put("guests", reservation.getGuests());
430	        map.put("ratePlan", reservation.getRatePlan().name());
431	        map.put("nights", reservation.getNights());
432	        map.put("subtotal", reservation.getSubtotal(room));
433	        map.put("discount", reservation.getDiscount(reservation.getSubtotal(room)));
434	        map.put("total", reservation.getTotal(room));
435	        map.put("status", reservation.getStatus().name());
436	        map.put("amountPaid", reservation.getAmountPaid());
437	        map.put("refund", reservation.getRefund());
438	        return map;
439	    }
440	
441	    private Map<String, Object> mapDocumentToResponse(Document document) {
442	        Map<String, Object> map = new HashMap<>();
443	        map.put("title", document.getTitle());
444	        map.put("reservationId", document.getReservationId());
445	        map.put("guestName", document.getGuestName());
446	        map.put("guestCpf", document.getGuestCpf());
447	        map.put("companyCnpj", document.getCompanyCnpj());
448	        map.put("companyName", document.getCompanyName());
449	        map.put("guestPassport", document.getGuestPassport());
450	        map.put("guestCountry", document.getGuestCountry());
451	        map.put("roomNumber", document.getRoomNumber());
452	        map.put("roomType", document.getRoomType().name());
453	        map.put("checkIn", document.getCheckIn());
454	        map.put("checkOut", document.getCheckOut());
455	        map.put("nights", document.getNights());
456	        map.put("subtotal", document.getSubtotal());
457	        map.put("discount", document.getDiscount());
458	        map.put("total", document.getTotal());
459	        map.put("text", document.getText());
460	        return map;
461	    }
462	}
