 41	package com.pousadamarealta.service;
 42	
 43	import com.pousadamarealta.domain.Reservation;
 44	import com.pousadamarealta.domain.Room;
 45	import com.pousadamarealta.repository.ReservationRepository;
 46	
 47	import java.math.BigDecimal;
 48	import java.sql.SQLException;
 49	import java.time.LocalDate;
 50	import java.time.format.DateTimeFormatter;
 51	import java.util.List;
 52	
 53	public class ReportService {
 54	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 55	
 56	    private final ReservationRepository reservationRepository;
 57	    private final RoomService roomService;
 58	
 59	    public ReportService(ReservationRepository reservationRepository, RoomService roomService) {
 60	        this.reservationRepository = reservationRepository;
 61	        this.roomService = roomService;
 62	    }
 63	
 64	    public String generateOccupancyReport(LocalDate date) throws SQLException {
 65	        List<Room> allRooms = roomService.getAllRooms();
 66	        StringBuilder csv = new StringBuilder();
 67	
 68	        csv.append("room,type,reservation,check_in,check_out\n");
 69	
 70	        int occupiedCount = 0;
 71	        for (Room room : allRooms) {
 72	            List<Reservation> reservations = reservationRepository.findByRoomAndDate(room.getNumber(), date);
 73	
 74	            if (!reservations.isEmpty()) {
 75	                for (Reservation reservation : reservations) {
 76	                    csv.append(room.getNumber()).append(",")
 77	                       .append(room.getType()).append(",")
 78	                       .append(reservation.getId()).append(",")
 79	                       .append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",")
 80	                       .append(reservation.getCheckOut().format(DATE_FORMATTER)).append("\n");
 81	                }
 82	                occupiedCount++;
 83	            }
 84	        }
 85	
 86	        csv.append("total,").append(occupiedCount).append("/").append(allRooms.size());
 87	
 88	        return csv.toString();
 89	    }
 90	
 91	    public String generateRevenueReport(int year, int month) throws SQLException {
 92	        List<Reservation> reservations = reservationRepository.findByMonth(year, month);
 93	        StringBuilder csv = new StringBuilder();
 94	
 95	        csv.append("reservation,room,check_in,check_out,status,amount\n");
 96	
 97	        BigDecimal total = BigDecimal.ZERO;
 98	
 99	        for (Reservation reservation : reservations) {
100	            Room room = roomService.getRoomByNumber(reservation.getRoomNumber())
101	                .orElseThrow(() -> new IllegalStateException("Room not found"));
102	
103	            BigDecimal netAmount = reservation.getAmountPaid();
104	            if (reservation.getRefund() != null) {
105	                netAmount = netAmount.subtract(reservation.getRefund());
106	            }
107	
108	            csv.append(reservation.getId()).append(",")
109	               .append(reservation.getRoomNumber()).append(",")
110	               .append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",")
111	               .append(reservation.getCheckOut().format(DATE_FORMATTER)).append(",")
112	               .append(reservation.getStatus()).append(",")
113	               .append(String.format("%.2f", netAmount)).append("\n");
114	
115	            total = total.add(netAmount);
116	        }
117	
118	        csv.append("total,").append(String.format("%.2f", total));
119	
120	        return csv.toString();
121	    }
122	}
