150	    public Reservation createReservation(Reservation reservation) throws SQLException {
151	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber())
152	            .orElseThrow(() -> new IllegalArgumentException("Room not found"));
153	
154	        if (reservation.getGuests() > room.getCapacity()) {
155	            throw new IllegalArgumentException("Capacity exceeded");
156	        }
157	
158	        if (reservationRepository.hasConflict(
159	                reservation.getRoomNumber(),
160	                reservation.getCheckIn(),
161	                reservation.getCheckOut(),
162	                null)) {
163	            throw new IllegalArgumentException("Room unavailable");
164	        }
165	
166	        return reservationRepository.save(reservation);
167	    }
