173	    public Reservation confirmReservation(Long id) throws SQLException {
174	        Reservation reservation = reservationRepository.findById(id)
175	            .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));
176	
177	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber())
178	            .orElseThrow(() -> new IllegalArgumentException("Room not found"));
179	
180	        if (!reservation.canConfirm()) {
181	            throw new IllegalStateException("Operation not allowed");
182	        }
183	
184	        reservation.confirm(reservation.getTotal(room));
