101	                .orElseThrow(() -> new IllegalStateException("Room not found"));
102	
103	            BigDecimal netAmount = reservation.getAmountPaid();
104	            if (reservation.getRefund() != null) {
105	                netAmount = netAmount.subtract(reservation.getRefund());
106	            }
107	
108	            csv.append(reservation.getId()).append(",")
109	               .append(reservation.getRoomNumber()).append(",")
