 72	package com.pousadamarealta.repository;
 73	
 74	import com.pousadamarealta.database.Database;
 75	import com.pousadamarealta.domain.RatePlan;
 76	import com.pousadamarealta.domain.Reservation;
 77	import com.pousadamarealta.domain.ReservationStatus;
 78	
 79	import java.math.BigDecimal;
 80	import java.sql.*;
 81	import java.time.LocalDate;
 82	import java.util.ArrayList;
 83	import java.util.List;
 84	import java.util.Optional;
 85	
 86	public class ReservationRepository {
 87	    private final Database database;
 88	
 89	    public ReservationRepository(Database database) {
 90	        this.database = database;
 91	    }
 92	
 93	    public Reservation save(Reservation reservation) throws SQLException {
 94	        if (reservation.getId() == null) {
 95	            return insert(reservation);
 96	        } else {
 97	            return update(reservation);
 98	        }
 99	    }
100	
101	    private Reservation insert(Reservation reservation) throws SQLException {
102	        String sql = """
103	            INSERT INTO reservations (
104	                room_number, guest_name, guest_email, guest_cpf, company_cnpj, company_name,
105	                guest_passport, guest_country, check_in, check_out, guests, rate_plan,
106	                status, amount_paid, refund
107	            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
108	            RETURNING id
109	        """;
110	
111	        try (Connection conn = database.getConnection();
112	             PreparedStatement stmt = conn.prepareStatement(sql)) {
113	
114	            setReservationParameters(stmt, reservation);
115	
116	            try (ResultSet rs = stmt.executeQuery()) {
117	                if (rs.next()) {
118	                    reservation.setId(rs.getLong("id"));
119	                }
120	            }
121	        }
122	
123	        return reservation;
124	    }
125	
126	    private Reservation update(Reservation reservation) throws SQLException {
127	        String sql = """
128	            UPDATE reservations SET
129	                room_number = ?, guest_name = ?, guest_email = ?, guest_cpf = ?,
130	                company_cnpj = ?, company_name = ?, guest_passport = ?, guest_country = ?,
131	                check_in = ?, check_out = ?, guests = ?, rate_plan = ?,
132	                status = ?, amount_paid = ?, refund = ?
133	            WHERE id = ?
134	        """;
135	
136	        try (Connection conn = database.getConnection();
137	             PreparedStatement stmt = conn.prepareStatement(sql)) {
138	
139	            setReservationParameters(stmt, reservation);
140	            stmt.setLong(16, reservation.getId());
141	            stmt.executeUpdate();
142	        }
143	
144	        return reservation;
145	    }
146	
147	    private void setReservationParameters(PreparedStatement stmt, Reservation r) throws SQLException {
148	        stmt.setString(1, r.getRoomNumber());
149	        stmt.setString(2, r.getGuestName());
150	        stmt.setString(3, r.getGuestEmail());
151	        stmt.setString(4, r.getGuestCpf());
152	        stmt.setString(5, r.getCompanyCnpj());
153	        stmt.setString(6, r.getCompanyName());
154	        stmt.setString(7, r.getGuestPassport());
155	        stmt.setString(8, r.getGuestCountry());
156	        stmt.setDate(9, Date.valueOf(r.getCheckIn()));
157	        stmt.setDate(10, Date.valueOf(r.getCheckOut()));
158	        stmt.setInt(11, r.getGuests());
159	        stmt.setString(12, r.getRatePlan().name());
160	        stmt.setString(13, r.getStatus().name());
161	        stmt.setBigDecimal(14, r.getAmountPaid());
162	        stmt.setBigDecimal(15, r.getRefund());
163	    }
164	
165	    public Optional<Reservation> findById(Long id) throws SQLException {
166	        String sql = """
167	            SELECT id, room_number, guest_name, guest_email, guest_cpf, company_cnpj,
168	                   company_name, guest_passport, guest_country, check_in, check_out,
169	                   guests, rate_plan, status, amount_paid, refund
170	            FROM reservations
171	            WHERE id = ?
172	        """;
173	
174	        try (Connection conn = database.getConnection();
175	             PreparedStatement stmt = conn.prepareStatement(sql)) {
176	
177	            stmt.setLong(1, id);
178	
179	            try (ResultSet rs = stmt.executeQuery()) {
180	                if (rs.next()) {
181	                    return Optional.of(mapReservation(rs));
182	                }
183	            }
184	        }
185	
186	        return Optional.empty();
187	    }
188	
189	    public boolean hasConflict(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeId) throws SQLException {
190	        String sql = """
191	            SELECT COUNT(*) FROM reservations
192	            WHERE room_number = ?
193	              AND status != 'CANCELLED'
194	              AND check_in < ?
195	              AND check_out > ?
196	              AND (? IS NULL OR id != ?)
197	        """;
198	
199	        try (Connection conn = database.getConnection();
200	             PreparedStatement stmt = conn.prepareStatement(sql)) {
201	
202	            stmt.setString(1, roomNumber);
203	            stmt.setDate(2, Date.valueOf(checkOut));
204	            stmt.setDate(3, Date.valueOf(checkIn));
205	            if (excludeId != null) {
206	                stmt.setLong(4, excludeId);
207	                stmt.setLong(5, excludeId);
208	            } else {
209	                stmt.setNull(4, Types.BIGINT);
210	                stmt.setNull(5, Types.BIGINT);
211	            }
212	
213	            try (ResultSet rs = stmt.executeQuery()) {
214	                if (rs.next()) {
215	                    return rs.getInt(1) > 0;
216	                }
217	            }
218	        }
219	
220	        return false;
221	    }
222	
223	    public List<Reservation> findByRoomAndDate(String roomNumber, LocalDate date) throws SQLException {
224	        String sql = """
225	            SELECT id, room_number, guest_name, guest_email, guest_cpf, company_cnpj,
226	                   company_name, guest_passport, guest_country, check_in, check_out,
227	                   guests, rate_plan, status, amount_paid, refund
228	            FROM reservations
229	            WHERE room_number = ?
230	              AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
231	              AND check_in <= ?
232	              AND check_out > ?
233	            ORDER BY id
234	        """;
235	
236	        try (Connection conn = database.getConnection();
237	             PreparedStatement stmt = conn.prepareStatement(sql)) {
238	
239	            stmt.setString(1, roomNumber);
240	            stmt.setDate(2, Date.valueOf(date));
241	            stmt.setDate(3, Date.valueOf(date));
242	
243	            List<Reservation> reservations = new ArrayList<>();
244	            try (ResultSet rs = stmt.executeQuery()) {
245	                while (rs.next()) {
246	                    reservations.add(mapReservation(rs));
247	                }
248	            }
249	
250	            return reservations;
251	        }
252	    }
253	
254	    public List<Reservation> findByMonth(int year, int month) throws SQLException {
255	        String sql = """
256	            SELECT id, room_number, guest_name, guest_email, guest_cpf, company_cnpj,
257	                   company_name, guest_passport, guest_country, check_in, check_out,
258	                   guests, rate_plan, status, amount_paid, refund
259	            FROM reservations
260	            WHERE EXTRACT(YEAR FROM check_in) = ?
261	              AND EXTRACT(MONTH FROM check_in) = ?
262	              AND (amount_paid > refund OR (refund IS NULL AND amount_paid > 0))
263	            ORDER BY check_in, id
264	        """;
265	
266	        try (Connection conn = database.getConnection();
267	             PreparedStatement stmt = conn.prepareStatement(sql)) {
268	
269	            stmt.setInt(1, year);
270	            stmt.setInt(2, month);
271	
272	            List<Reservation> reservations = new ArrayList<>();
273	            try (ResultSet rs = stmt.executeQuery()) {
274	                while (rs.next()) {
275	                    reservations.add(mapReservation(rs));
276	                }
277	            }
278	
279	            return reservations;
280	        }
281	    }
282	
283	    private Reservation mapReservation(ResultSet rs) throws SQLException {
284	        Reservation reservation = new Reservation();
285	        reservation.setId(rs.getLong("id"));
286	        reservation.setRoomNumber(rs.getString("room_number"));
287	        reservation.setGuestName(rs.getString("guest_name"));
288	        reservation.setGuestEmail(rs.getString("guest_email"));
289	        reservation.setGuestCpf(rs.getString("guest_cpf"));
290	        reservation.setCompanyCnpj(rs.getString("company_cnpj"));
291	        reservation.setCompanyName(rs.getString("company_name"));
292	        reservation.setGuestPassport(rs.getString("guest_passport"));
293	        reservation.setGuestCountry(rs.getString("guest_country"));
294	        reservation.setCheckIn(rs.getDate("check_in").toLocalDate());
295	        reservation.setCheckOut(rs.getDate("check_out").toLocalDate());
296	        reservation.setGuests(rs.getInt("guests"));
297	        reservation.setRatePlan(RatePlan.valueOf(rs.getString("rate_plan")));
298	        reservation.setStatus(ReservationStatus.valueOf(rs.getString("status")));
299	        reservation.setAmountPaid(rs.getBigDecimal("amount_paid"));
300	
301	        BigDecimal refund = rs.getBigDecimal("refund");
302	        if (!rs.wasNull()) {
303	            reservation.setRefund(refund);
304	        }
305	
306	        return reservation;
307	    }
308	}
