 11	public class CorporateDocumentGenerator implements DocumentGenerator {
 12	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 13	    private static final BigDecimal ISS_RATE = new BigDecimal("0.05");
 14	
 15	    @Override
 16	    public Document generate(Reservation reservation, Room room) {
 17	        Document document = new Document();
 18	        document.setTitle("Fatura de hospedagem");
 19	        document.setReservationId(reservation.getId());
 20	        document.setGuestName(reservation.getGuestName());
 21	        document.setGuestCpf(null);
 22	        document.setCompanyCnpj(reservation.getCompanyCnpj());
 23	        document.setCompanyName(reservation.getCompanyName());
 24	        document.setGuestPassport(null);
 25	        document.setGuestCountry(null);
 26	        document.setRoomNumber(room.getNumber());
 27	        document.setRoomType(room.getType());
 28	        document.setCheckIn(reservation.getCheckIn());
 29	        document.setCheckOut(reservation.getCheckOut());
 30	        document.setNights(reservation.getNights());
 31	
 32	        BigDecimal subtotal = reservation.getSubtotal(room);
 33	        BigDecimal discount = reservation.getDiscount(subtotal);
 34	        BigDecimal total = reservation.getTotal(room);
 35	
 36	        document.setSubtotal(subtotal);
 37	        document.setDiscount(discount);
 38	        document.setTotal(total);
 39	        document.setText(generateText(document));
 40	
 41	        return document;
 42	    }
 43	
 44	    private String generateText(Document doc) {
 45	        StringBuilder sb = new StringBuilder();
 46	        sb.append("Fatura de hospedagem nº ").append(doc.getReservationId()).append("\n");
 47	        sb.append("Empresa: ").append(doc.getCompanyName())
 48	          .append(" (CNPJ ").append(doc.getCompanyCnpj()).append(")\n");
 49	        sb.append("Hóspede: ").append(doc.getGuestName()).append("\n");
 50	        sb.append("Quarto: ").append(doc.getRoomNumber())
 51	          .append(" (").append(doc.getRoomType()).append(")\n");
 52	        sb.append("Entrada: ").append(doc.getCheckIn().format(DATE_FORMATTER))
 53	          .append(" | Saída: ").append(doc.getCheckOut().format(DATE_FORMATTER))
 54	          .append(" | ").append(formatNights(doc.getNights())).append("\n");
 55	        sb.append("Diárias: ").append(formatMoney(doc.getSubtotal())).append("\n");
 56	
 57	        if (doc.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
 58	            sb.append("Desconto: ").append(formatMoney(doc.getDiscount())).append("\n");
 59	        }
 60	
 61	        sb.append("Total: ").append(formatMoney(doc.getTotal())).append("\n");
 62	
 63	        BigDecimal iss = doc.getTotal().multiply(ISS_RATE).setScale(2, RoundingMode.HALF_EVEN);
 64	        sb.append("ISS retido (5%): ").append(formatMoney(iss));
 65	
 66	        return sb.toString();
 67	    }
 68	
 69	    private String formatMoney(BigDecimal amount) {
 70	        return String.format("R$ %,.2f", amount).replace(',', '_').replace('.', ',').replace('_', '.');
 71	    }
 72	
 73	    private String formatNights(int nights) {
 74	        return nights == 1 ? "1 diária" : nights + " diárias";
 75	    }
 76	}
